(function(root){
'use strict';
const A=x=>Array.isArray(x)?x:[],esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),num=x=>Number.isFinite(Number(x))?Number(x):0,fmt=x=>Number.isInteger(num(x))?String(num(x)):num(x).toFixed(1),sign=x=>num(x)>0?'+':'';
const byId=id=>document.getElementById(id),status={active:'仍在继续',paused:'暂时搁置',completed:'已经完成',ended:'已经收束',abandoned:'这一轮结束',pending:'尚待兑现',fulfilled:'已经兑现',broken:'没有兑现',open:'仍可争取',closed:'已经关上',expired:'已经错过'};
function box(id,html,hidden=false){const el=byId(id);if(!el)return;el.hidden=hidden;el.innerHTML=html;}
function resourceHeader(c){const r=c?.resources||{};return`<div class="campaign-resource-pair"><div><span>生活缓冲</span><strong>${fmt(r.cashMonths)}<small>个月</small></strong></div><div><span>本年每周还可安排</span><strong>${fmt(r.freeHours)}<small>小时</small></strong></div></div>`;}
function dueList(c,year){return A(c?.commitments).filter(x=>x.status==='pending'&&num(x.dueYear)<=year+1);}
function promiseCard(x,year){return`<article class="campaign-promise ${num(x.dueYear)<=year&&x.status==='pending'?'due':''}"><span>${esc(status[x.status]||x.status)}${x.dueYear?' · '+esc(x.dueYear)+'年':''}</span><strong>${esc(x.label)}</strong>${x.requires?.min!==undefined?`<p>${x.status==='pending'?'须留出':'当时约定留出'} ${fmt(x.requires.min)} ${x.requires.resource==='cashMonths'?'个月生活缓冲':'小时／周'}。</p>`:''}</article>`;}
function dutyCard(x,{live,onRelease}={}){return`<article class="campaign-duty"><span>${esc(status[x.status]||x.status)}</span><strong>${esc(x.label)}</strong><p>每周 ${fmt(x.hours)} 小时${num(x.cashMonths)?` · 每年${num(x.cashMonths)>0?'回流':'支出'} ${fmt(Math.abs(num(x.cashMonths)))} 个月预算`:''}${x.untilYear||x.endYear?' · 至 '+esc(x.untilYear||x.endYear)+' 年':''}</p>${live&&onRelease&&x.status==='active'?`<button data-release-duty="${esc(x.id)}">结束这项安排${num(x.exitCost)?' · 需 '+fmt(x.exitCost)+' 月预算':''} ↗</button>`:''}</article>`;}
function arcCard(a){return`<article class="campaign-thread"><div><span>${esc(status[a.status]||'仍在继续')}${a.startedYear?' · '+esc(a.startedYear)+'年开始':''}</span><strong>${esc(a.title)}</strong></div><p>${esc(a.stageTitle||'下一步尚待选择')}</p><div class="campaign-progress"><i style="width:${Math.max(0,Math.min(100,num(a.progress)))}%"></i></div></article>`;}
function relationshipCard(p){const memories=A(p.memories),last=memories.at(-1);return`<article class="campaign-person"><div><strong>${esc(p.label||p.name)}</strong><span title="模拟关系值，非现实测量">信任 ${fmt(p.trust)}</span></div><p class="campaign-person-need">${esc(p.need||'有自己的打算与日程')}</p>${last?`<details><summary>还记着 ${esc(last.year)} 年的这件事</summary><p>${esc(last.text)}</p>${memories.slice(-4,-1).reverse().map(m=>`<p><time>${esc(m.year)}</time> ${esc(m.text)}</p>`).join('')}</details>`:''}</article>`;}
function opportunityCard(o){return`<article class="campaign-door ${esc(o.status)}"><span>${esc(status[o.status]||o.status)}${o.status==='open'&&o.expiresYear?' · '+esc(o.expiresYear)+'年到期':o.updatedYear?' · '+esc(o.updatedYear)+'年':''}</span><strong>${esc(o.label)}</strong>${o.reason?`<p>${esc(o.reason)}</p>`:''}</article>`;}
function impactMarkup(record){
 const raw=A(record?.turningPoints),semantic=raw.filter(p=>!['low','high','turn'].includes(p.type)),points=semantic.length?semantic:raw,causes=A(record?.stateCauses),seen=new Set();
 if(!points.length&&!causes.length)return'';
 const labels={'ending':'一段故事的结局','commitment-broken':'一次没有兑现的约定','promise-broken':'约定没有兑现','promise-kept':'约定兑现了','relationship-turn':'一个人改变了答复','opportunity-turn':'一扇门的开与关','opportunity-expired':'一个窗口已经错过','project-ending':'一段故事的结局','project-pause':'这件事先暂停','ongoing-duty':'下一年的时间已被预订','duty-ending':'给长期安排一个交代','duty-expired':'该重新商量了','trial-return':'试住结束后的返回','low':'余地正在收窄','high':'投入开始接上'};
 return`<div class="campaign-section-title"><span>THE CONSEQUENCES</span><h3>这一年，留下了什么</h3></div>${record.domainEffects?`<p class="campaign-change-line">本次决定：生活缓冲 ${sign(record.domainEffects.resources?.cashMonths)}${fmt(record.domainEffects.resources?.cashMonths)} 月 · 每周余时 ${sign(record.domainEffects.resources?.freeHours)}${fmt(record.domainEffects.resources?.freeHours)} 小时</p>`:''}${points.map(p=>{const show=p.text&&p.text!==record.decision?.outcome&&p.text!==record.summary&&!seen.has(p.text);seen.add(p.text);return`<article class="campaign-turn ${esc(p.type||'change')}"><span>${esc(labels[p.type]||'一个转折')}</span><h4>${esc(p.title)}</h4>${show?`<p>${esc(p.text)}</p>`:''}</article>`;}).join('')}${causes.length?`<details class="campaign-ledger"><summary>今年的时间与预算怎样变化 · ${causes.length} 条</summary><ul>${causes.map(line=>`<li>${esc(typeof line==='string'?line:line.text||'')}</li>`).join('')}</ul></details>`:''}`;
}

function render({run,record,year,onRelease,onJournal}){
 const c=run?.campaign;if(!run||!c)return;
 const active=A(c.activeArcs).filter(a=>['active','paused'].includes(a.status)),duties=A(c.ongoingDuties).filter(d=>d.status==='active'),due=dueList(c,run.year),arc=record?.arc;
 box('campaign-budget',`<div class="section-heading"><h2>日历与生活缓冲</h2><span>${run.year}</span></div>${resourceHeader(c)}<p class="campaign-budget-note">两项均为游戏资源；每年的收支与占用可逐项查看。</p>${due.slice(0,2).map(p=>promiseCard(p,run.year)).join('')}${duties.length?`<details class="campaign-duties"><summary>${duties.length} 项长期安排正在占用时间</summary>${duties.map(d=>dutyCard(d,{live:true,onRelease})).join('')}</details>`:''}<button class="campaign-board-link" data-campaign-journal>查看局面与未完的事 ↗</button>`,run.year<2026);
 let hub='';
 if(arc){const index=num(arc.stageIndex)+1,total=num(arc.totalStages)||1;hub=`<div class="campaign-hub-top"><span>这一年正在续写</span><small>第 ${index} / ${total} 幕</small></div><h3>${esc(arc.title)}</h3><div class="campaign-act-track">${Array.from({length:total},(_,i)=>`<i class="${i<index-1?'done':i===index-1?'now':''}"></i>`).join('')}</div><p>${esc(arc.stageTitle||record.title)}</p>${record.decision?.selectedOptionId?'<span class="campaign-resolved">这一幕的决定已写下，下一年会带着它继续。</span>':'<span class="campaign-awaiting">这个选择会影响后面的几幕。</span>'}<button data-campaign-journal>还有哪些事牵着下一年？ ↗</button>`;}
 else if(year===2026)hub=`<div class="campaign-hub-top"><span>下一年的生活，从这里继续</span><small>2027 →</small></div><h3>作品、同伴和一张真正有限的日历</h3><p>钱会花掉，答应的事会到期，别人也有自己的选择。下一页开始，一段故事会留下几年后的回声。</p><button data-campaign-journal>先看看眼前的局面 ↗</button>`;
 box('campaign-hub',hub,!hub);
 const people=record?.campaign?.relationships||(year===run.year?c.relationships:[]);
 box('campaign-people',`<div class="section-heading"><h2>与你共同生活的人</h2><small>${year}</small></div>${A(people).slice(0,3).map(relationshipCard).join('')}<p class="campaign-cast-note">小岑、阿远等为模拟中的虚构人物。</p>`,!A(people).length||year<2026);
 const impact=year>2026?impactMarkup(record):'';box('campaign-impact',impact,!impact);
 document.querySelectorAll('[data-release-duty]').forEach(button=>button.addEventListener('click',()=>onRelease?.(button.dataset.releaseDuty)));
 document.querySelectorAll('[data-campaign-journal]').forEach(button=>button.addEventListener('click',()=>onJournal?.()));
}
function journal(run,record,{controls=false}={}){const c=record?.campaign||run.campaign;if(!c)return'<p>长线故事从2027年开始。</p>';const year=record?.year||run.year;return`<p class="campaign-journal-intro">${year} 年的局面。未完成的故事与约定会继续占用时间，关掉的机会不会因为翻到下一年就自动回来。</p>${resourceHeader(c)}<h3>仍在继续的故事</h3>${A(c.activeArcs).filter(a=>['active','paused'].includes(a.status)).map(arcCard).join('')||'<p>下一年的主题与手头条件会带来新的故事。</p>'}<h3>说过要做的事</h3>${A(c.commitments).slice(-10).reverse().map(p=>promiseCard(p,year)).join('')||'<p>眼下还没有跨年的承诺。</p>'}<h3>长期安排</h3>${A(c.ongoingDuties).map(d=>dutyCard(d,{live:controls&&year===run.year,onRelease:controls})).join('')||'<p>尚未承担需要年年维护的安排。</p>'}<h3>还开着和已经关掉的门</h3>${A(c.opportunities).slice(-14).reverse().map(opportunityCard).join('')||'<p>新的机会会随着经历与选择出现。</p>'}<h3>人物与留下的记忆</h3>${A(c.relationships).map(relationshipCard).join('')}<h3>最近的收支与时间</h3><div class="campaign-ledger-lines">${A(c.ledger).filter(x=>num(x.year)<=year).slice(-12).reverse().map(x=>`<p><time>${esc(x.year)}</time> ${esc(x.text)}</p>`).join('')||'<p>从第一年的行动开始记录。</p>'}</div>`;}
function choiceExtras(option){const future=option.futureCost||option.delayedText;return`${future?`<div class="campaign-choice-future"><span>${option.futureType==='present'?'这一次会留下':'接下来还要承担'}</span><p>${esc(String(future).replace(/^当下的结果[：:]\s*/,''))}</p></div>`:''}${A(option.opens).length||A(option.closes).length?`<div class="campaign-choice-doors">${A(option.opens).map(x=>`<span class="open">保留：${esc(typeof x==='string'?x:x.label)}</span>`).join('')}${A(option.closes).map(x=>`<span class="closed">失去：${esc(typeof x==='string'?x:x.label)}</span>`).join('')}</div>`:''}`;}
root.TANG_CAMPAIGN_VIEW=Object.freeze({render,journal,choiceExtras,resourceHeader,impactMarkup});
})(typeof window!=='undefined'?window:globalThis);
